const RULES = `Read docs/northstar/plans/workflows_2026-10-07/rules.md first (git show origin/main:docs/northstar/plans/workflows_2026-10-07/rules.md); your role's section is your rule set; stage files by name only, never git add -A or commit -a; commit messages end with the line Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>. Rules: model Sonnet 5.5; never spawn sub-agents; think tersely; your last message is the report, no interim notices; report once, in the schema. Run no command that can raise a permission prompt (Westley 2026-10-13): the target of rm, git worktree remove and kill is always a literal, fully written-out path (no $VAR, glob or $(...) there); if a command might be destructive or unresolvable, do not run it, leave the item and list it in your report. Worktree ONLY by absolute path: git -C ~/Projects/ouroboros-manifold fetch -q && git -C ~/Projects/ouroboros-manifold worktree add -b <branch> ~/Projects/om-push/wt/<suffix> origin/main (if that fails, stop and report; never run git with the live checkout as the working tree). Never touch ~/Projects/ouroboros-manifold itself. No stash/rebase/amend/force; never make clean; never push to main. Build: make && make pipe/ouroboros_pipe pipe/ouroboros_pipe_dbg; godot.real --headless --import first when Godot is needed. Godot ~/.local/bin/godot.real (4.6.3); Godot tests under timeout 1800 scripts/run_godot_tests.sh <file>; display-needing Godot tests under timeout 1800 xvfb-run -a -s '-screen 0 1920x1080x24' godot.real --path . --resolution 1920x1080 -s <file>; long runs inside systemd-run --user --scope -q -p MemoryMax=6G -p MemorySwapMax=0 -- nice -n 10 <cmd>. Python ~/Projects/ouroboros-manifold/.venv/bin/python. Builders never edit tests; a test that looks wrong stops the piece with stop_reason "test-defect: <test id> | <failing assertion line> | <the spec line it contradicts, file:line>". Liberties and named drafts in the spec are taken as written and marked in a code comment; anything else undecided stops the piece. Determinism: plain double arithmetic (fabs and fmin only), no libm transcendentals, no sqrt in the trigger (compare squared distance), no wall clock, no hash-order iteration; every constant a named #define; new world state is saved and hashed. Never stage *.import or *.uid. Pre-gate before every push (rules.md section (a)): scripts/specfactory/pre_gate.sh <worktree> origin/main <piece ids> <your test file> must end "PRE_GATE verdict OK"; quote the verdict in your report. Ledger merge conflicts keep both sides. Push your branch, write .wt-done (date, branch, sha). Stop past 120k context. ${BASE_NOTE}`
const REPORT = { type: 'object', properties: { ok: { type: 'boolean' }, branch: { type: 'string' }, sha: { type: 'string' }, summary: { type: 'string' }, red_ids: { type: 'array', items: { type: 'string' } }, stop_reason: { type: 'string' }, parked: { type: 'array', items: { type: 'string' } } }, required: ['ok', 'branch', 'sha', 'summary'] }
const VERDICT = { type: 'object', properties: { pass: { type: 'boolean' }, blocking: { type: 'boolean' }, evidence: { type: 'string' } }, required: ['pass', 'evidence'] }
const PREFLIGHT = { type: 'object', properties: { pass: { type: 'boolean' }, blocking: { type: 'boolean' }, evidence: { type: 'string' }, abi_from: { type: 'number' }, abi_main: { type: 'number' }, abi_to: { type: 'number' }, save_from: { type: 'number' }, save_to: { type: 'number' }, e7_landed: { type: 'boolean' }, extra_pieces: { type: 'array', items: { type: 'string' } }, unlisted_pins: { type: 'array', items: { type: 'string' } } }, required: ['pass', 'evidence', 'abi_from', 'abi_to'] }
const RULING = { type: 'object', properties: { ruled: { type: 'boolean' }, row: { type: 'string' }, branch: { type: 'string' }, brief: { type: 'string' } }, required: ['ruled'] }
const done = (label) => SKIP[label] ? { ok: true, branch: SKIP[label], sha: 'skipped', summary: `skipped: ${SKIP[label]} already ok` } : null
const rulingMerge = () => RULINGS ? `, origin/${RULINGS}` : ''
const PREGATE = (wt, tests) => `MERGE_GATE_PIECES=${wt}/docs/northstar/plans/push/pieces.toml scripts/specfactory/pre_gate.sh ${wt} origin/main ${PIECES}${tests ? ' ' + tests : ''}`

// A builder's test-defect stop goes to the ruler (rules.md section (e)); a ruled test re-runs the builder once with the rulings branch merged; anything else returns the brief for the Architect.
const ruler = (r, phaseName) => agent(`${RULES}\nRole: ruler (Engineer), rules.md section (e). Builder branch origin/${r.branch} stopped with: ${r.stop_reason}\nSpec: ${SPEC}. Rulebook: docs/northstar/plans/2026-10-07-visible-game-rulebook.md (its "Decision procedure" word for word; lane E ledger rows are TD-VG-E-<n> in docs/northstar/plans/push_ledger_2026-09-22.md, next free number after the highest present). Branch ${RB} (suffix ${RB.replace('push/', '')}; continue it from origin if it exists: worktree add ~/Projects/om-push/wt/${RB.replace('push/', '')} origin/${RB} then git checkout -B ${RB}, else from the base). A golden is never a pinned literal you may move; a golden that moves in this piece is a finding for the Architect, ruled false. If every condition of the procedure holds: edit only the one test file named, run it alone and its positive control, append the ledger row, push, report ruled true with row and branch. Else report ruled false and brief (under one page: test id and failing line, the builder's claim, the spec and bible lines that bear on it, two or three options with what each changes).`, { label: `rule:${r.branch}`, phase: phaseName, schema: RULING, agentType: 'engineer', model: 'sonnet' })
const withRuling = async (mk, phaseName) => {
  let r = await mk('')
  if (r && !r.ok && /^test-defect:/.test(r.stop_reason || '')) {
    const v = await ruler(r, phaseName)
    if (v && v.ruled && v.branch) { r = await mk(`, origin/${v.branch} (ruling ${v.row})`); r = { ...r, ruling: v } } else { r = { ...r, ruling: v } }
  }
  return r
}
