if (!(docs && docs.ok && tests && tests.ok)) return { ...out, stopped: 'docs-tests' }

phase('Build')
const STOPS = `STOP RULES: (a) a file outside your list, a number nobody gave, a pipe frame (tactical, mission, snapshot) change, a public header change other than the ONE declaration of the g2 ruling and OM_ABI_VERSION (no enum value: g3 is arg == 1), a new public symbol other than the g2 one, a golden table edit, or an edit to any test: ok=false, stop_reason says which; (b) a test of the old om_command_set_layer users (tests/csim/test_PP_C_g4_*.py, test_E01_R001_07_walking_kind.py, test_PP_unit_guard.py, test_PP_C_g3_transition_sight.py, tests/transport/test_pipe_vg_contract.py, tests/test_c_bridge_vg.gd) that is green on the base and red on your branch: STOP 'old-path-moved: <id>' with the failing line; (c) any existing golden, checksum or save pin other than the ones the ledger row moves that turns red: STOP 'golden-moved: <id>' (the fold-when-set hash must leave every world with no queued spot hashing exactly as before); (d) a hash-order, wall-clock, libm or sqrt use in the trigger; (e) a test that looks wrong: test-defect stop per section (a) of the rules.`
const mkCore = (extra) => done('core') || agent(`${RULES}\nRole: Doer (rules.md section (a)) for VG-CONTRACT-layerspot of ${SPEC}, the SIM half (the contract is documented in docs/architecture.md on the docs branch; the tests branch holds the red test). ${VERS}.${GAPTXT} Branch push/vg-ls-core, suffix vg-ls-core, from ${BASE}; merge origin/${docs.branch}, origin/${tests.branch}${rulingMerge()}${extra}. Edit ONLY: ${SRC_FILES.filter(f => !/cmd_stream|om_pipe|c_bridge/.test(f)).join(', ')}. Build exactly: (1) Contract: add ONE row to docs/northstar/spec_factory/signatures.toml for the g2 declaration (module tactical_move.c, epics E-01, confidence certain, note: 'optional spot: each listed unit walks to (x, y) and makes its hard transfer when within one lattice pitch of it (VG-CONTRACT-layerspot, See also om_command_set_layer); 0 ok, -1 refused.'), run scripts/specfactory/sig_table.py --emit (it writes the header declaration, a STUB body into the generated-stubs block of csrc/tactical_move.c and the conftest bind; replace the stub with the real body, do not leave a second definition) and --check (exit 0); OM_ABI_VERSION ${ABI_TO} with its comment in csrc/ouroboros_sim.h. (2) csrc/tactical_move.c: a named #define for the pitch, P = 2.0 * OM_UNIT_COLLISION_RADIUS (30.0 wu) with the comment 'See also csrc/mission.c om_mission_spawn_force: spacing = 2.0 * OM_UNIT_COLLISION_RADIUS (the lattice pitch)'; factor the per-unit body of om_command_set_layer (:3141-3156: walker skip, touch, lay_any, transit 0, guard off, in-flight pending or pending/none) into ONE static helper used by both entry points, the old entry point behaving byte-identically; the queued state exactly as the g1 ruling says (fields, fold-when-set hash, mv_row_is_fresh, save and load order, lay_any set so the layer pass runs); the new entry point: reject with -1 a layer outside OM_LAYER_COUNT or a null id list or a non-finite x or y (tested with plain comparisons only: x != x, x - x != 0.0; never isfinite, isnan or any libm call: libm_lint STOP (d)), per g8 and g10, walkers per g7, then for each live unit that can take a layer order call om_command_move with the clamped spot (g6 ruling (b): per unit, NOT om_command_group_move, so no formation and no speed cap) and queue the transfer in the unit's own spot fields; the trigger inside om_move_layer_unit or a small pass called from om_move_layer_pass (ascending unit id, squared distance against P * P in plain doubles with <=, plus the walk-ended rule of g4), which on firing clears the queued state and calls the helper (so R-002-01 to R-002-06 apply from that moment); the superseding rule exactly as the g5 ruling says (hooks in om_command_move and om_command_guard ONLY, both in this file; attack-move and attack-target cancel through om_command_move; no hook in om_command_direct_move or the kiting path); the walk-end rule of g13: om_move_giveup_pass (it skips group_id 0, and om_command_move sets group_id 0) is extended to a unit with a queued spot, reusing OM_GROUP_GIVEUP_RADIUS and OM_GROUP_GIVEUP_TICKS from csrc/om_constants.h:591-592 and the pass's existing counters; NO new threshold and NO new constant; if the pass needs a counter that is not already saved and hashed, STOP 'giveup-needs-field' instead of adding one; for a unit with no queued spot the pass is unchanged byte for byte; when the pass ends the walk of a spot-queued unit (has_dest drops) the transfer fires there (g4); the layer pass must visit a unit whose only reason is a queued transfer (the skip at :2429 must not drop it). (3) ${SAVE_BUMP ? 'Versions: OM_SAVE_FORMAT_VERSION ' + SAVE_TO + ' (csrc/om_internal.h, prepend "bumped ' + SAVE_FROM + ' -> ' + SAVE_TO + ' (VG layerspot: the queued layer transfer in the move state): version-' + SAVE_FROM + ' saves are refused, no migration (R-111-03)" to the comment chain), OM_PIPE_SAVE_FORMAT_VERSION ' + SAVE_TO + ', scenes/load_game/load_game.gd CURRENT_SAVE_VERSION ' + SAVE_TO + ', the history comments at csrc/checksum_full.c:34 and csrc/terrain.c:34.' : 'No save version change (args.saveBump false).'} No pipe, cmd_stream or bridge change in this branch (the wire builder does those next). STOP rules: ${STOPS} Done when ${TEST_FILE} sections 0 to 6 are green (section 7 needs the wire branch and may stay red here: say which), the moved pins are green, scripts/specfactory/sig_table.py --check, libm_lint (scripts/libm_lint.py), scripts/alg_constants.py --lint and the reach lint pass (the new symbol is reached by the wire branch: if the reach lint rejects it here, say so and do not allowlist it), and the old users of om_command_set_layer are green. Pre-gate with ${PIECES} and the test files. Report ok, branch, sha, summary, red_ids.`, { label: 'build:layerspot-core', phase: 'Build', schema: REPORT, agentType: 'doer', model: 'sonnet' })
const core = await withRuling(mkCore, 'Build')
out = { ...out, core }
if (!(core && core.ok)) return { ...out, stopped: 'build-core' }
const mkWire = (extra) => done('wire') || agent(`${RULES}\nRole: Doer (rules.md section (a)) for VG-CONTRACT-layerspot of ${SPEC}, the WIRE half. ${VERS}.${GAPTXT} Branch push/vg-ls-wire, suffix vg-ls-wire, from ${BASE}; merge origin/${docs.branch}, origin/${tests.branch}, origin/${core.branch}${rulingMerge()}${extra}. Edit ONLY: csrc/cmd_stream.c, csrc/pipe/om_pipe.c, autoload/c_bridge.gd${EXTRA_FILES.length ? ', ' + EXTRA_FILES.join(', ') : ''} (and csrc/pipe/pipe_net.c only if the g3 ruling needs it, and say so). Build exactly: (1) csrc/cmd_stream.c apply_one, case OM_NET_VERB_SET_LAYER: call the new entry point with c->x and c->y when the entry says a spot is present per the g3 ruling, else om_command_set_layer as today; nothing else in the file (pack and unpack already carry arg, x, y for every verb; an old log entry replays as before). (2) csrc/pipe/om_pipe.c verb set_layer (:1590-1593): read x and y with get_f64 (nonzero when the key is present); both present: call the new entry point (ret as the verb does today); neither present: exactly the old line; exactly one present: ret = 1 (the error "command failed"), per g8; layer < 0 stays ret 1. (3) autoload/c_bridge.gd send_unit_command, set_layer branch (:476-477): add pipe_cmd x and y (floats) ONLY when cmd has both keys x and y; a dictionary without them sends exactly what it sends today (tests/test_c_bridge_vg.gd:143 pins {verb, units, layer}); the comment above the function and the architecture.md pointer stay true. Do not touch scenes/tactical_c/tactical_view.gd (MATCH_VERBS and the arg flag on the client are VG-A-layerkeys's). STOP rules: ${STOPS} Done when ${TEST_FILE} is fully green (sections 0 to 7), the moved pins are green, the old users of om_command_set_layer and tests/transport/test_pipe_vg_contract.py, tests/transport/test_pipe_net_verbs.py, tests/transport/test_pipe_command_cap.py and the Godot tests tests/test_c_bridge_vg.gd and ${TEST_BRIDGE} are green, make pipe/ouroboros_pipe pipe/ouroboros_pipe_dbg builds, the reach lint passes with the new symbol reached from cmd_stream.c and om_pipe.c (no allowlist entry needed; if one is demanded STOP and say so). Pre-gate with ${PIECES} and the test files. Report ok, branch, sha, summary, red_ids.`, { label: 'build:layerspot-wire', phase: 'Build', schema: REPORT, agentType: 'doer', model: 'sonnet' })
const wire = await withRuling(mkWire, 'Build')
out = { ...out, wire }
if (!(wire && wire.ok)) return { ...out, stopped: 'build-wire' }

phase('Check')
const checks = await parallel([
  checkOne(docs, 'chk-ls-docs', `Only docs/architecture.md changed; every claim this piece makes wrong is rewritten (grep for "abi\\":${ABI_FROM}", "${ABI_FROM} since", "set_layer {units, layer}", "0 to 8"${SAVE_BUMP ? ', "format ' + SAVE_FROM + '"' : ''} and quote what remains and why it is still true); the new paragraph states the signature of the g2 ruling, the optional x and y rule, the 30 wu pitch and the g4 trigger, the g5 and g6 and g7 rules, the lockstep flag of the g3 ruling, the storage of the g1 ruling and the version numbers ${ABI_TO}${SAVE_BUMP ? ' and ' + SAVE_TO : ''}, and says no frame changes shape; no number appears that the rulings and the bible do not give; the bible is untouched.`),
  checkOne(tests, 'chk-ls-tests', `Only ${TEST_FILES.join(', ')} (park files aside), the pins named by the Preflight, and ONE ledger row changed; ${TEST_FILE} holds exactly ONE test function (count them) and quotes R-002-08, R-002-01 to R-002-05, R-001-07 and the ruling word for word in its header; on the base the file is red for the missing symbol om_command_set_layer_at and section 0 (the control) is green (paste both lines); every pin is red on the base for the stated reason and moved ${ABI_FROM} -> ${ABI_TO}${SAVE_BUMP ? ' and ' + SAVE_FROM + ' -> ' + SAVE_TO : ''} in the ledger row with old and new values; the premises are dumped; no golden or threshold was edited or loosened; the old users of om_command_set_layer are untouched.`),
  checkOne(core, 'chk-ls-core', `The diff versus its merge base touches only the core file list; the header diff is exactly the g2 declaration and OM_ABI_VERSION ${ABI_TO} (nm -g old versus new shows exactly one new symbol, om_command_set_layer_at, and om_command_set_layer is unchanged in signature); the per-unit body of om_command_set_layer is one static helper used by both entry points; the trigger uses squared distance, ascending unit id, no sqrt, libm or clock; every queued field is in mv_row_is_fresh, the hash (folded only when set, so a world with no queued spot hashes exactly as before), the save writer and the loader in the same order; the cancel hooks of the g5 ruling sit in tactical_move.c, in om_command_move and om_command_guard only; the give-up extension of the g13 ruling is in om_move_giveup_pass, uses OM_GROUP_GIVEUP_RADIUS and OM_GROUP_GIVEUP_TICKS, adds no #define, no constant and no unsaved field, and leaves the pass untouched for a unit with no queued spot (quote the diff); sig_table.py --check exits 0; libm_lint and alg_constants --lint pass. Then, read-only and uncommitted, load the base library and the branch library in one Python process via distinct paths and, on the fixtures of the old users of om_command_set_layer and a 200-step world with 6 units and moves (no spot order), compare om_world_checksum_full every 10 steps and the move-section hash: they must be IDENTICAL between the two libraries${SAVE_BUMP ? ' (the save bytes differ only by the new fields and the version word)' : ' (the save bytes are identical)'}; report any difference with the first step. Run the old users (tests/csim/test_PP_C_g4_transfer.py, test_PP_C_g4_routing.py, test_PP_C_g3_transition_sight.py, test_E01_R001_07_walking_kind.py, test_PP_unit_guard.py, test_VG_E_e1h.py) and ${TEST_FILE} sections 0 to 6.`),
  checkOne(wire, 'chk-ls-wire', `The diff versus its merge base touches only csrc/cmd_stream.c, csrc/pipe/om_pipe.c, autoload/c_bridge.gd (and what the g3 ruling names); an old command (no x, y; or verb 4 arg 0 with any x, y) takes exactly the old path (quote the lines); exactly-one-of x, y answers "command failed"; the bridge sends x and y only when both keys are in the dictionary and ${TEST_BRIDGE} is green on the branch (red with c_bridge.gd reverted); no pipe frame changed shape (git diff of docs and csrc/pipe shows no field added to tactical, mission or snapshot); ${TEST_FILE} is fully green and red again with the wire branch's changes reverted (second detached worktree, never stash); the reach lint passes with no new allowlist entry; the pipe builds (make pipe/ouroboros_pipe pipe/ouroboros_pipe_dbg).`),
  () => agent(`${RULES.replace('worktree add -b <branch>', 'worktree add --detach')}\nRole: join checker (Engineer), rules.md section (c), detached worktree of ${BASE} (suffix chk-ls-join; remove it after with git worktree remove, no --force); merge origin/${docs.branch}, origin/${tests.branch}, origin/${core.branch}, origin/${wire.branch}${rulingMerge()} into it locally, no push (conflicts mean the lanes overlap: report them). Spec: ${SPEC}.${GAPTXT} Build; run ${TEST_FILE}, the moved pins, the whole csim and transport suites, tests/test_c_bridge_vg.gd, ${TEST_BRIDGE} and tests/test_load_game_wrong_version.gd under scripts/run_godot_tests.sh; compare the sorted red id list with the base's (detached worktree of ${BASE}, suffix chk-ls-base). Expected: no red id that the base does not also have, apart from the known-red tests of the FINDING-gd-red-main-2026-10-12 row that are still red on the base; every other new red is COLLATERAL: list it with the decisive line and say whether it calls om_command_set_layer, hashes a move section, or pins a save or ABI value; collateral fails the check and goes to the Architect (not fixed, not re-pinned here). WIRING (rules: wired, not just tested; gap g11 null action): drive a THROWAWAY pipe session (uncommitted, in your TMPDIR, using the helpers of tests/transport/test_pipe_vg_contract.py:214, the same SET_SEED, start(), BEGIN frames) against pipe/ouroboros_pipe: (i) command set_layer with units, layer, x, y for one player flyer: ack, the unit shows no tl for the first ticks, then tl == the target layer (state bit 4) once within 30 wu of the spot (paste the tick, the distance and the frame row); (ii) the same command without x and y: tl appears on the first step (the old path, same as test_pipe_vg_contract.py:214); (iii) only x: error name command reason "command failed"; (iv) a lockstep session (tests/transport/test_pipe_net_verbs.py shows the net_submit and net_step frames): net_submit a verb 4 entry carrying the g3 flag with x, y at the next net tick, net_step, and the unit transfers at the spot; the same entry without the flag transfers in place; (v) the throwaway byte-compare of two identical lockstep sessions' net_ack checksums. Paste the frames. ${WESTLEY_NOTE} Report pass, evidence (each red id and its decisive line; each frame).`, { label: 'check:join', phase: 'Check', schema: VERDICT, agentType: 'engineer', model: 'sonnet' }),
])
out = { ...out, checks }
if (checks.some((c) => !(c && c.pass))) return { ...out, stopped: 'check' }

phase('Clerk')
const clerk = await agent(`${RULES}\nRole: landing clerk (Engineer), rules.md section (b). ${PUSH_MAIN ? 'The push to main at the end IS authorised on a clean gate, subject to the known-red rule and the stack rule below.' : 'Do NOT push to main (args.pushMain false): branch only.'} Piece VG-CONTRACT-layerspot of ${SPEC}; a contract piece, not player-facing. ${WESTLEY_NOTE} STACK RULE: ${STACKED ? 'this piece is stacked on ' + BASE_REFS.join(', ') + '. For each of those refs run git merge-base --is-ancestor <ref> origin/main (after git fetch origin). If EVERY ref is an ancestor (the stack landed), merge origin/main instead of the stack refs and the push to main is allowed under the other rules. If ANY is not, you land NOTHING on main: stop at the branch push/vg-ls-land, put "stacked on <refs>, not landed" at the top of the summary, still run the pre-gate and the tests, and report; the Dispatcher relaunches you alone after the stack lands (args.skip for every other label).' : 'not stacked (no baseRef): normal landing; first confirm origin/main reads OM_ABI_VERSION ' + ABI_FROM + ' (the E7 value) and say so.'} Branch push/vg-ls-land, suffix vg-ls-land, from ${BASE}; merge origin/${docs.branch}, origin/${tests.branch}, origin/${core.branch}, origin/${wire.branch}${rulingMerge()} (stage files by name; never git add -A or git commit -a; keep *.import and *.uid noise out: delete any untracked .uid before a checkout or merge). If origin/main moved the ABI past ${ABI_FROM} since the Preflight (another contract piece landed), STOP with 'abi-moved: main reads <n>' and push nothing: the Dispatcher relaunches from the Preflight. Build; run ${TEST_FILE}, every moved pin, tests/test_c_bridge_vg.gd and ${TEST_BRIDGE} (PASS/FAIL per file). Pre-gate before the lock (section (b)): ${PREGATE('<landing worktree>', TEST_FILE)}; it must end PRE_GATE verdict OK (the piece list is ONE comma-joined third argument; with more than one id the acceptance and undertest steps WARN and skip: list those WARN lines and run the acceptance file yourself). A reject on lint, footprint, owner row or noise is fixed or reported before the lock, never spent on a full gate. Full gate per section (b), from the worktree, detached with setsid nohup into <TMPDIR>/gate.log, the lock taken first and origin/main fetched and merged inside it (main moves while a clerk waits for the lock): mkdir -p ~/Projects/om-push/tmp-vg-ls; flock ~/Projects/om-push/gate.lock env TMPDIR=$HOME/Projects/om-push/tmp-vg-ls MERGE_GATE_SUITE_TIMEOUT=2400 MERGE_GATE_PLAYTHROUGH_TIMEOUT=2400 MERGE_GATE_PLAY_TIMEOUT=900 MERGE_GATE_PIECES=<worktree>/docs/northstar/plans/push/pieces.toml bash -c 'cd <worktree> && git fetch origin && git merge --no-edit origin/main && scripts/specfactory/pre_gate.sh <worktree> origin/main ${PIECES} && scripts/specfactory/merge_gate.sh <worktree> origin/main ${PIECES}' (three positional arguments to each script; the last is ONE comma list; add any extra owner id the Preflight named: ${(pre.extra_pieces || []).join(', ') || 'none'}, and re-run the pre-gate; the pre-gate above is the cheap early check and pre_gate runs again inside the lock, on the tree after the merge; the script rejects a candidate that lacks the current origin/main, so a forgotten merge costs seconds, not a gate). Poll gate.log for the ^GATE look line with one foreground command under 10 minutes at a time, every 5 minutes at most; then pgrep -f '^bash scripts/specfactory/merge_gate.sh' to confirm no gate for the worktree still runs (never pgrep your own command line). There is no VERDICT line: the verdict is the set of GATE <stage> REJECT lines. Flake rule per section (b). KNOWN-RED RULE (section (b), Architect 2026-10-12): push main only when EVERY GATE REJECT line names a test or play listed by exact id in scripts/specfactory/lane_plays_known_red.txt or, once B23 has landed, ${KNOWN_RED} on the landing tree; a reject outside those files means branch only, every REJECT line quoted, never a push; this piece moves no golden, so a golden reject is a STOP for the Architect, not a listing (playthrough_known_red.txt stays empty). test_tactical_delta_reconstruction, test_time_jump_replay and test_vg_e_e1p may still be red on main until their pieces land: they are listed or they reject; do not fix them. The playthrough stage is the wired check (the plain move and layer paths must still pass). In the landing commit: flip the VG-CONTRACT-layerspot row in docs/northstar/plans/push/pieces.toml to attached with the landing sha (comment 'landed <sha7>'), set tests_pending false; close the TD row of the Tests step with the sha in the ledger; in docs/northstar/plans/2026-10-07-visible-game-programme.md edit ONLY the lane table row that names this piece (Preflight item 8) - On main: 'layerspot at <sha7>: set_layer takes an optional spot, ABI ${ABI_TO}; approved-not-integrated: the client does not send it until VG-A-layerkeys' and Next piece: 'VG-A-layerkeys'; if no row names this piece, edit nothing there and say so; write nothing about status anywhere else; no shot and no story_reviews row (not player-facing); docs/bible and stories.md are NOT edited. Then fetch origin and merge origin/main right before the push (say whether it moved; if it moved re-run the pre-gate, not the full gate, and say so); commit with a normal-prose subject (the subject is the journal) ending with the attribution line the conversation gives (Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>); push the branch to origin as push/vg-ls-land${PUSH_MAIN ? ', then git push origin HEAD:main only under the known-red rule and the stack rule' : ''}. Else branch only, every GATE REJECT line quoted. Write .wt-done after the push; remove only the merge_gate_before_* directories under your own TMPDIR, by literal path. Report ok, branch, sha, summary (the stack-rule outcome, every GATE REJECT line or "OK per stage", the WARN lines, the pre-gate verdict, main head), red_ids.`, { label: 'clerk:layerspot', phase: 'Clerk', schema: REPORT, agentType: 'engineer', model: 'sonnet' })
return { ...out, clerk, next: 'VG-A-layerkeys can send the spot once this lands (its g5 candidate d): the Dispatcher passes it the ABI and the arg flag of the g3 ruling; the TD row of the pin moves stays with this landing; if the clerk stopped at the branch because the stack has not landed, relaunch the clerk alone (args.skip for the other labels) after VG-CONTRACT-E7 lands' }
